window.INTEGRATED_CHAPTER_DATA = window.INTEGRATED_CHAPTER_DATA || {};
window.INTEGRATED_CHAPTER_DATA["physics-chemistry"] = [{"id": "physics-chemistry-001", "chapter": 2, "chapterTitle": "基礎的な物理・化学", "itemNo": 1, "title": "燃焼と燃焼の三要素", "intro": "<p>燃焼とは、物質が酸素と激しく反応し、熱や光を発生する現象です。</p><p>燃焼を続けるには、燃える物である可燃物、酸素を供給する酸素供給源、燃え始めるきっかけとなる点火源の三つが必要です。第4類危険物では、液体から発生した蒸気が可燃物となります。</p><p>要点では、三要素の具体例と、どの要素を取り除くと除去・窒息・冷却などの消火につながるかを押さえます。</p>", "introImage": "images/physics-chemistry-001.png", "introImageAlt": "燃焼と燃焼の三要素を示すイラスト", "body": "<p>燃焼とは、物質が<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-001-m001\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">酸素</span>と反応し、<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-001-m002\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">熱と光</span>を発する現象である。</p><ul><li>燃焼の三要素は、次の三つである。</li><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-001-m003\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">　</span><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-001-m004\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">可燃物</span>：ガソリン、灯油、木材など。</li><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-001-m005\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">　</span><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-001-m006\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">酸素供給源</span>：空気中の酸素など。</li><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-001-m007\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">　</span><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-001-m008\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">点火源</span>：炎、電気火花、静電気の放電火花など。</li><li>空気中の酸素は約21 vol％で、通常は酸素供給源となる。vol％は体積の割合を表す。</li><li>三要素のいずれかを取り除くと、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-001-m009\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">燃焼を継続できなくなる</span>。</li><li>炎を伴う燃焼では、<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-001-m010\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">連鎖反応</span>を燃焼の第4の要素として扱うことがある。これを抑える消火が<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-001-m011\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">抑制消火</span>である。</li></ul>", "questions": [{"id": "physics-chemistry-001-q001", "questionNo": 1, "question": "<strong>燃焼の三要素のうち、いずれか１つを取り除くことで消火が成立する理由として、正しいものはどれか。</strong>", "choices": ["三要素はすべて同時に存在しなくても燃焼が継続するため。", "三要素のいずれか１つでも欠けると、燃焼反応自体が成立しなくなるため。", "三要素は燃焼開始時のみ必要で、継続には不要であるため。", "三要素という概念は消火理論には適用されない。"], "answer": 2, "explanation": "解説：燃焼は、可燃物・酸素供給源・点火源の三要素がそろうことで成立します。いずれか１つでも欠けると燃焼は成立しないため、消火は三要素のどれかを崩す考え方になります。"}, {"id": "physics-chemistry-001-q002", "questionNo": 2, "question": "<strong>燃焼の三要素に加え、第４の要素として扱われることがあるものはどれか。</strong>", "choices": ["燃焼範囲", "燃焼の継続（連鎖反応）", "燃焼速度", "燃焼温度"], "answer": 2, "explanation": "解説：燃焼の継続、つまり連鎖反応を第４の要素とする考え方があります。この連鎖反応を止める消火法が、抑制効果または負触媒効果です。"}]}, {"id": "physics-chemistry-002", "chapter": 2, "chapterTitle": "基礎的な物理・化学", "itemNo": 2, "title": "燃焼のしかた", "intro": "<p>物質は、気体・液体・固体という状態や性質によって、燃え方が異なります。</p><p>第4類危険物の液体は、液体そのものではなく、液面から発生した蒸気が空気と混ざって燃える『蒸発燃焼』をします。固体には、熱で分解して出たガスが燃えるものや、表面だけが燃えるものもあります。</p><p>要点では、拡散燃焼・予混合燃焼・蒸発燃焼・分解燃焼・表面燃焼などと代表物質を対応させます。</p>", "introImage": "images/physics-chemistry-002.png", "introImageAlt": "燃焼のしかたを示すイラスト", "body": "<h3><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-002-m001\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">気体燃焼</span></h3><p><span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-002-m002\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">可燃性ガスそのもの</span>が燃える燃焼である。</p><p>気体燃焼は、空気との混ざり方によって次の二つに分けられる。</p><ul><li>拡散燃焼：可燃性ガスと空気が、燃焼しながら混ざる。ガスの拡散炎など。</li><li>予混合燃焼：可燃性ガスと空気が、あらかじめ混ざった状態で燃える。</li></ul><h3><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-002-m003\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">蒸発燃焼</span></h3><p>液面などから<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-002-m004\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">蒸発した可燃性蒸気</span>が燃える。</p><ul><li>第4類危険物の多くは<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-002-m005\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">蒸発燃焼</span>である。液体そのものではなく、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-002-m006\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">液体から出た蒸気</span>が燃える。</li></ul><h3><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-002-m007\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">分解燃焼</span></h3><p>加熱によって物質が分解し、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-002-m008\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">発生した可燃性ガス</span>が燃える。</p><ul><li><span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-002-m009\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">木材</span>や<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-002-m010\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">石炭</span>などが代表例である。</li></ul><h3><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-002-m011\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">表面燃焼</span></h3><p>可燃性ガスをほとんど発生せず、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-002-m012\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">固体の表面で直接</span>燃える。</p><ul><li><span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-002-m013\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">木炭</span>や<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-002-m014\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">コークス</span>などが代表例である。</li></ul><h3><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-002-m015\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">自己燃焼</span></h3><p>物質中に燃焼を助ける<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-002-m016\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">酸素</span>を含み、外部から<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-002-m017\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">酸素</span>が供給されなくても燃える。</p><ul><li><span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-002-m018\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">セルロイド</span>などが代表例である。</li></ul>", "questions": [{"id": "physics-chemistry-002-q001", "questionNo": 3, "question": "<strong>拡散燃焼と予混合燃焼の違いに関する記述として、正しいものはどれか。</strong>", "choices": ["拡散燃焼は、可燃性ガスと空気があらかじめ混合された状態で燃焼する。", "予混合燃焼は、可燃性ガスが空気中に拡散しながら燃焼する。", "拡散燃焼の例としてガスバーナーの炎、予混合燃焼の例としてガソリンエンジン内の燃焼が挙げられる。", "拡散燃焼と予混合燃焼は、固体の燃焼形式の分類である。"], "answer": 3, "explanation": "解説：拡散燃焼はガスが空気中に拡散しながら燃える形式、予混合燃焼は可燃性ガスと空気があらかじめ混ざった状態で燃える形式です。"}, {"id": "physics-chemistry-002-q002", "questionNo": 4, "question": "<strong>第４類危険物の液体の燃え方として、最も重要なものはどれか。</strong>", "choices": ["表面燃焼", "分解燃焼", "蒸発燃焼", "自己燃焼"], "answer": 3, "explanation": "解説：第４類危険物のほとんどは、液体そのものではなく、液面から蒸発した蒸気が燃える蒸発燃焼です。引火点や燃焼範囲の理解にもつながります。"}, {"id": "physics-chemistry-002-q003", "questionNo": 5, "question": "<strong>固体の燃焼形式のうち、木炭の燃焼に該当するものとして、正しいものはどれか。</strong>", "choices": ["分解燃焼", "表面燃焼", "蒸発燃焼", "自己燃焼"], "answer": 2, "explanation": "解説：木炭は、可燃性ガスを発生せず、固体表面で酸素と反応して燃える表面燃焼です。"}, {"id": "physics-chemistry-002-q004", "questionNo": 6, "question": "<strong>物質と主な燃焼形態の組合せとして、正しいものはどれか。</strong>", "choices": ["ガソリン－蒸発燃焼、木材－分解燃焼、木炭－表面燃焼", "ガソリン－表面燃焼、木材－蒸発燃焼、木炭－分解燃焼", "ガソリン－自己燃焼、木材－表面燃焼、木炭－蒸発燃焼", "ガソリン－分解燃焼、木材－自己燃焼、木炭－表面燃焼"], "answer": 1, "explanation": "解説：第4類危険物の多くは蒸発燃焼、木材などは分解燃焼、木炭・コークスなどは表面燃焼です。物質名と燃焼形態を組にして覚えます。"}]}, {"id": "physics-chemistry-003", "chapter": 2, "chapterTitle": "基礎的な物理・化学", "itemNo": 3, "title": "燃えやすさを左右する条件", "intro": "<p>同じ物質でも、温度、形状、水分、周囲の酸素量などによって燃えやすさは変わります。</p><p>温度が高いほど蒸気が発生しやすく、細かく砕いて表面積が大きくなるほど酸素と接触しやすくなります。乾燥や予熱も燃焼を促し、熱を逃がしにくい物質は温度が上がりやすくなります。</p><p>要点では、条件を一つ変えたときに燃えやすくなるか、燃えにくくなるかを判断します。</p>", "introImage": "images/physics-chemistry-003.png", "introImageAlt": "燃えやすさを左右する条件を示すイラスト", "body": "<p>物質の燃えやすさは、いくつかの条件によって左右される。</p><ul><li>酸化<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-003-m001\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">されやすい</span>物質ほど、燃えやすい。</li><li>周囲温度が<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-003-m002\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">高い</span>ほど、点火に必要な温度へ達しやすいため、燃えやすい。</li><li>発熱量が<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-003-m003\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">大きい</span>ほど、燃焼によって高い温度を保ちやすいため、燃えやすい。</li><li>熱伝導率が<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-003-m004\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">小さい</span>物質は、熱が周囲へ逃げにくいため、燃えやすい。</li><li>水分が少なく、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-003-m005\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">乾燥している</span>ほど燃えやすい。</li><li>粉末化すると、同じ質量でも空気と触れる<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-003-m006\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">表面積</span>が大きくなり、燃えやすい。</li></ul>", "questions": [{"id": "physics-chemistry-003-q001", "questionNo": 7, "question": "<strong>物質が燃えにくくなる条件として、正しいものはどれか。</strong>", "choices": ["比表面積が大きいこと", "周囲の温度が高いこと", "熱伝導率が大きいこと", "乾燥していること"], "answer": 3, "explanation": "解説：熱伝導率が大きい物質は、熱が周囲に逃げやすく蓄熱しにくいため、燃えにくくなります。"}, {"id": "physics-chemistry-003-q002", "questionNo": 8, "question": "<strong>比表面積が燃焼の難易に与える影響として、正しいものはどれか。</strong>", "choices": ["比表面積が大きいほど、空気との接触面積が小さくなり燃えにくい。", "比表面積が大きいほど、空気との接触面積が大きくなり燃えやすい。", "比表面積は燃焼の難易に影響しない。", "比表面積は液体にのみ適用される概念である。"], "answer": 2, "explanation": "解説：比表面積が大きいほど空気との接触面積が増え、酸化反応が進みやすくなるため燃えやすくなります。粉状・薄い形状ほど危険です。"}]}, {"id": "physics-chemistry-004", "chapter": 2, "chapterTitle": "基礎的な物理・化学", "itemNo": 4, "title": "引火点と発火点", "intro": "<p>危険物が燃えるためには、液体から発生した蒸気が空気と混ざり、火や高温によって着火する必要があります。</p><p>火を近づけたときに燃え始める最低温度が引火点で、火を近づけなくても自ら燃え始める最低温度が発火点です。通常、発火点は引火点より高く、引火点が低い物質ほど常温でも可燃性蒸気を生じやすくなります。</p><p>要点では、両者の定義と危険性の高低を押さえます。なお、試験では引火点と発火点の説明を入れ替えた選択肢に注意します。</p>", "introImage": "images/physics-chemistry-004.png", "introImageAlt": "引火点と発火点を示すイラスト", "body": "<h3><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-004-m001\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">引火点</span></h3><p>可燃性液体から出る蒸気に<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-004-m002\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">点火源</span>を近づけたとき、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-004-m003\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">引火できる</span>最低の液温。</p><ul><li>引火には<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-004-m004\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">点火源</span>が必要。</li><li>引火点が低い物質ほど、低い液温でも引火に必要な<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-004-m005\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">蒸気</span>を出すため<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-004-m006\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">、引火</span>しやすい。</li></ul><h3><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-004-m007\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">発火点</span></h3><p>可燃物を加熱したとき、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-004-m008\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">外部の点火源</span>がなくても<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-004-m009\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">自ら燃え始める</span>最低の温度。</p><ul><li>一般に、同じ物質では発火点は引火点より<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-004-m010\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">高い</span>。ただし、測定値は測定方法や条件の影響を受ける。</li></ul>", "questions": [{"id": "physics-chemistry-004-q001", "questionNo": 9, "question": "<strong>引火点の定義として、正しいものはどれか。</strong>", "choices": ["点火源がなくても自然に燃焼を開始する最低の温度", "可燃性液体の表面から発生する蒸気が、点火源によって燃焼することができる最低の液温", "可燃性液体が完全に蒸発し終える温度", "可燃性液体が沸騰を開始する温度"], "answer": 2, "explanation": "解説：引火点は、蒸気が点火源によって燃え始める最低の液温です。点火源が必要である点が発火点との違いです。"}, {"id": "physics-chemistry-004-q002", "questionNo": 10, "question": "<strong>発火点に関する記述として、正しいものはどれか。</strong>", "choices": ["点火源がなくても自ら発火する最低温度である。", "点火源があれば燃え始める最低の液温である。", "発火点は必ず引火点より低い。", "発火点と引火点は同じ意味である。"], "answer": 1, "explanation": "解説：発火点は、点火源がなくても自ら発火する最低温度です。一般に、同じ物質では発火点は引火点より高くなります。"}]}, {"id": "physics-chemistry-005", "chapter": 2, "chapterTitle": "基礎的な物理・化学", "itemNo": 5, "title": "燃焼範囲", "intro": "<p>可燃性ガスや蒸気は、空気中に少しでもあれば燃えるわけではありません。</p><p>濃度が薄すぎると燃料が足りず、濃すぎると酸素が足りないため、その中間の濃度だけが燃焼できます。この範囲を燃焼範囲といい、最も薄い濃度を下限界、最も濃い濃度を上限界といいます。</p><p>要点では、vol％の意味と、下限界が低い・燃焼範囲が広い物質ほど危険性が高い理由を理解します。</p>", "introImage": "images/physics-chemistry-005.png", "introImageAlt": "燃焼範囲を示すイラスト", "body": "<p><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-005-m001\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">燃焼範囲</span>とは、可燃性ガスや可燃性蒸気が空気中で燃焼できる<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-005-m002\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">濃度範囲</span>である。</p><ul><li>燃焼できる最も低い濃度を<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-005-m003\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">燃焼下限界</span>、最も高い濃度を<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-005-m004\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">燃焼上限界</span>という。</li><li>燃焼下限界より低い濃度では、可燃性ガスや蒸気が<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-005-m005\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">薄すぎる</span>。</li><li>燃焼上限界より高い濃度では、可燃性ガスや蒸気が<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-005-m006\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">濃すぎる</span>。（<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-005-m007\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">酸素</span>が不足する）</li><li>燃焼範囲は通常、vol％で表す。1 vol％は、混合気体100 L中に対象の気体や蒸気が1 Lある体積割合を示す。</li><li>液温が引火点に達したとき、液面付近の蒸気濃度は、おおむね<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-005-m008\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">燃焼下限界</span>に達する。</li><li>燃焼範囲が広い物質や、燃焼下限界が低い物質は、燃焼できる混合気をつくりやすい。</li></ul>", "questions": [{"id": "physics-chemistry-005-q001", "questionNo": 11, "question": "<strong>燃焼範囲が広い物質ほど危険性が高いとされる理由として、正しいものはどれか。</strong>", "choices": ["燃焼が起こり得る濃度の幅が広く、さまざまな状況で燃焼条件が成立しやすいため。", "燃焼範囲が広いほど、引火点が必ず高くなるため。", "燃焼範囲の広さは、危険性とは無関係であるため。", "燃焼範囲が広いほど、発火点が必ず低くなるため。"], "answer": 1, "explanation": "解説：燃焼範囲が広いほど、燃焼が起こり得る蒸気濃度の幅が広く、危険な混合気を作りやすくなります。"}, {"id": "physics-chemistry-005-q002", "questionNo": 12, "question": "<strong>燃焼下限値が低い物質の危険性に関する記述として、正しいものはどれか。</strong>", "choices": ["燃焼下限値が低いほど、わずかな蒸気でも燃焼条件が成立しやすく危険性が高い。", "燃焼下限値が低いほど、燃焼条件が成立しにくく危険性が低い。", "燃焼下限値の高低は、危険性の判断には使用されない。", "燃焼下限値は、常に燃焼上限値より大きい。"], "answer": 1, "explanation": "解説：燃焼下限値が低い物質は、少量の蒸気でも燃焼範囲に入りやすいため危険です。"}, {"id": "physics-chemistry-005-q003", "questionNo": 13, "question": "<strong>引火点と燃焼範囲の関係として、正しいものはどれか。</strong>", "choices": ["液温が引火点に達すると、蒸気濃度は燃焼下限値に達する。", "液温が引火点に達すると、蒸気濃度は燃焼上限値を必ず超える。", "引火点と燃焼範囲には関係がない。", "引火点は、燃焼範囲の幅そのものを表す。"], "answer": 1, "explanation": "解説：引火点は、蒸気濃度が燃焼下限値に達し、点火源があれば燃焼できるようになる液温として理解できます。"}]}, {"id": "physics-chemistry-006", "chapter": 2, "chapterTitle": "基礎的な物理・化学", "itemNo": 6, "title": "自然発火と粉じん爆発", "intro": "<p>火花や炎がなくても、酸化・分解・吸着などで生じた熱が逃げずに蓄積すると、物質が自ら発火することがあります。</p><p>これが自然発火です。また、可燃性の粉じんが空気中に浮遊すると、広い表面が一度に燃えて爆発することがあります。</p><p>要点では、乾性油の付いた布などの自然発火例と、粉じんの粒径・濃度・酸素・点火源といった粉じん爆発の条件を押さえます。</p>", "introImage": "images/physics-chemistry-006.png", "introImageAlt": "自然発火と粉じん爆発を示すイラスト", "body": "<h3><strong><mark class=\"marker-yellow\">自然発火</mark></strong></h3><ul><li>外部から直接加熱されなくても、物質内部で生じた<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-006-m001\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">熱が蓄積し</span>、発火する現象。</li></ul><p>原因となる熱には、次のようなものがある。</p><ul><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-006-m002\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">酸化熱</span>：<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-006-m003\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">乾性油</span>が付いた布、石炭、ゴム粉など。</li><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-006-m004\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">分解熱</span>：<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-006-m005\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">セルロイド</span>、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-006-m006\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">ニトロセルロース</span>など。</li><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-006-m007\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">吸着熱</span>：<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-006-m008\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">活性炭</span>など。</li><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-006-m009\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">発酵熱</span>：堆肥など。</li><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-006-m010\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">重合熱</span>：一部のモノマーなど。</li><li>防止の基本は、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-006-m011\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">熱をためない</span>こと。通気・換気、低温保管、堆積量を減らすことなどが有効。</li><li>油が染みた布は放置せず、ふたのできる不燃性の金属容器などに入れて管理する。</li></ul><h3><mark class=\"marker-yellow\">粉じん爆発</mark></h3><ul><li>可燃性の微粉が<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-006-m012\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">空気中に浮遊</span>し、点火源に触れて<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-006-m013\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">急激に燃焼</span>する現象。</li><li>爆発が起こり得る濃度範囲があり、薄すぎても濃すぎても爆発は起こりにくい。</li><li><span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-006-m014\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">粒子が細かい</span>、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-006-m015\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">乾燥している</span>、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-006-m016\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">空間が閉鎖されている</span>などの条件で起こりやすい。</li><li>防止策は、粉じんを<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-006-m017\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">堆積・浮遊</span>させないこと、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-006-m018\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">点火源</span>をなくすこと、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-006-m019\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">換気や集じん</span>を行うこと。</li></ul>", "questions": [{"id": "physics-chemistry-006-q001", "questionNo": 14, "question": "<strong>自然発火の原因のうち、「分解熱」が原因となる物質として、正しいものはどれか。</strong>", "choices": ["アマニ油", "セルロイド", "活性炭", "堆肥"], "answer": 2, "explanation": "解説：セルロイドは、分解に伴って発生する分解熱により自然発火することがあります。アマニ油は酸化熱、活性炭は吸着熱、堆肥は発酵熱が代表例です。"}, {"id": "physics-chemistry-006-q002", "questionNo": 15, "question": "<strong>自然発火を防止する方法として、誤っているものはどれか。</strong>", "choices": ["通気・換気をよくして、熱が蓄積しないようにする。", "油の染みた布等は、密閉した金属製容器に入れて保管する。", "物質を高温で保管し、酸化を促進させる。", "物質を低温で保管し、周囲温度の上昇を避ける。"], "answer": 3, "explanation": "解説：高温で保管して酸化を促進させることは、自然発火の危険を高めるため不適切です。"}, {"id": "physics-chemistry-006-q003", "questionNo": 16, "question": "<strong>粉じん爆発に関する記述として、正しいものはどれか。</strong>", "choices": ["粉じんの水分が多いほど爆発しやすい。", "粉じんの濃度が高ければ高いほど、常に爆発しやすくなる。", "粉じんにも、爆発が起こり得る濃度範囲が存在する。", "粉じん爆発は、液体にのみ生じる現象である。"], "answer": 3, "explanation": "解説：粉じんにも、気体の燃焼範囲と同様に爆発が起こり得る濃度範囲があります。薄すぎても濃すぎても爆発は起こりにくくなります。"}]}, {"id": "physics-chemistry-007", "chapter": 2, "chapterTitle": "基礎的な物理・化学", "itemNo": 7, "title": "消火の四原理", "intro": "<p>火を消すには、燃焼を支えている条件のどれかを取り除きます。</p><p>可燃物をなくす除去消火、酸素を遮る窒息消火、温度を下げる冷却消火、燃焼の連鎖反応を止める抑制消火の四つが基本です。実際の消火方法は、一つの原理だけでなく複数が働く場合もあります。</p><p>要点では、元栓を閉める、泡で覆う、水で冷やす、粉末を放射するなどの具体例を、どの原理に当たるか判断します。</p>", "introImage": "images/physics-chemistry-007.png", "introImageAlt": "消火の四原理を示すイラスト", "body": "<h3><mark class=\"marker-yellow\">除去消火</mark></h3><ul><li>可燃物を取り除き、<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-007-m001\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">燃料の供給</span>を断つ。</li><li>ガスの元栓を閉める、周囲の可燃物を移すなどが例である。</li></ul><h3><mark class=\"marker-yellow\">窒息消火</mark></h3><ul><li>酸素の供給を断つか、周囲の<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-007-m002\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">酸素濃度</span>を下げる。</li><li><span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-007-m003\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">泡消火剤</span>や<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-007-m004\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">二酸化炭素消火剤</span>などが、主にこの作用を利用する。</li></ul><h3><mark class=\"marker-yellow\">冷却消火</mark></h3><ul><li>燃焼物を、燃焼が継続できない温度まで<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-007-m005\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">冷やす</span>。</li><li>水は大きな冷却作用をもつ。</li></ul><h3><mark class=\"marker-yellow\">抑制消火</mark></h3><ul><li>燃焼の<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-007-m006\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">連鎖反応</span>を抑える。</li><li><span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-007-m007\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">粉末消火剤</span>や<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-007-m008\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">ハロゲン化物消火剤</span>などが、主にこの作用を利用する。</li></ul>", "questions": [{"id": "physics-chemistry-007-q001", "questionNo": 17, "question": "<strong>消火の三要素に当たらないものはどれか。</strong>", "choices": ["除去消火", "窒息消火", "冷却消火", "蒸発消火"], "answer": 4, "explanation": "解説：基本的な消火法は、可燃物を取り除く除去消火、酸素を遮る窒息消火、温度を下げる冷却消火です。"}, {"id": "physics-chemistry-007-q002", "questionNo": 18, "question": "<strong>第４の消火法として位置付けられるものはどれか。</strong>", "choices": ["希釈消火", "抑制消火（負触媒消火）", "拡散消火", "蒸発消火"], "answer": 2, "explanation": "解説：燃焼の連鎖反応を阻害する消火法を、抑制消火または負触媒消火といいます。"}]}, {"id": "physics-chemistry-008", "chapter": 2, "chapterTitle": "基礎的な物理・化学", "itemNo": 8, "title": "電気の基礎", "intro": "<p>電気火花や過熱した電気機器は、第4類危険物の蒸気に着火する点火源になります。</p><p>そのため、電圧・電流・抵抗・電力の基本を理解しておく必要があります。電圧は電流を流そうとする力、電流は電気の流れ、抵抗は流れにくさです。</p><p>要点では、オームの法則V＝IR、電力P＝VIを使った簡単な計算と、直列・並列回路の基本を押さえます。</p>", "introImage": "images/physics-chemistry-008.png", "introImageAlt": "電気の基礎を示すイラスト", "body": "<p>電気火花や静電気の<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-008-m001\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">放電火花</span>は、第4類危険物の蒸気に対する<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-008-m002\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">点火源</span>になり得る。</p><ul><li>電圧は、電流を流そうとする働きである。記号はV、単位はボルト（V）。</li><li>電流は、電気の流れである。記号はI、単位はアンペア（A）。</li><li>抵抗は、電流の流れにくさである。記号はR、単位はオーム（Ω）。</li><li>電力は、電気エネルギーが使われる速さを表す。記号はP、単位はワット（W）。</li></ul><h3>オームの法則</h3><ul><li>`V＝IR`</li><li>電流を求めるときは、I＝V÷R</li><li>抵抗を求めるときは、R＝V÷I</li><li>電力は、P＝VIで求める。オームの法則を使うと、P＝I²Rと表すこともできる。</li></ul>", "questions": [{"id": "physics-chemistry-008-q001", "questionNo": 19, "question": "<strong>電圧10V、抵抗5Ωの回路に流れる電流として、正しいものはどれか。</strong>", "choices": ["0.5A", "2A", "5A", "50A"], "answer": 2, "explanation": "解説：オームの法則 V＝IR より、I＝V÷R＝10÷5＝2A です。"}, {"id": "physics-chemistry-008-q002", "questionNo": 20, "question": "<strong>電力10W、電圧5Vの回路に流れる電流として、正しいものはどれか。</strong>", "choices": ["0.5A", "2A", "5A", "50A"], "answer": 2, "explanation": "解説：電力の式 P＝VI より、I＝P÷V＝10÷5＝2A です。"}]}, {"id": "physics-chemistry-009", "chapter": 2, "chapterTitle": "基礎的な物理・化学", "itemNo": 9, "title": "静電気", "intro": "<p>物体同士の摩擦や、危険物が配管・ホース内を流れることで電子が移動し、静電気が発生します。</p><p>静電気が蓄積して放電すると小さな火花が生じ、可燃性蒸気の点火源になることがあります。特に空気が乾燥し、流速が速く、電気を通しにくい液体を扱う場合は注意が必要です。</p><p>要点では、接地、加湿、流速低下、静かな注入などの防止策を判断します。</p>", "introImage": "images/physics-chemistry-009.png", "introImageAlt": "静電気を示すイラスト", "body": "<p>通常の帯電では、原子核中の<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-009-m001\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">陽子</span>は物体間を移動せず、主に<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-009-m002\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">電子</span>が移動する。</p><ul><li>電子を失った物体は<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-009-m003\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">正</span>に帯電する、電子を受け取った物体は<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-009-m004\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">負</span>に帯電する。</li><li>物体間で電子が移動しても、全体の電気量の総和は<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-009-m005\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">変わらない</span>。</li><li>同じ符号の電荷どうしは<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-009-m006\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">反発</span><span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-009-m007\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">し</span>、異なる符号の電荷どうしは<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-009-m008\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">引き合う</span>。</li><li>静電気は、異なる物質の<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-009-m009\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">接触・摩擦・はく離</span>、液体の<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-009-m010\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">流動・ろ過・噴出</span>などで発生する。</li><li><span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-009-m011\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">電気を通しにくい物質</span>、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-009-m012\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">乾燥した環境</span>、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-009-m013\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">高速の流動</span>では、静電気が蓄積しやすい。</li><li>主な対策は、設備の<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-009-m014\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">接地</span>、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-009-m015\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">導電性</span>材料の使用、流速の<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-009-m016\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">低下</span>、適切な<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-009-m017\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">加湿</span>である。</li><li>タンクへ液体を注入するときは、落差を<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-009-m018\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">小さくし</span>、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-009-m019\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">タンク底部付近</span>から<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-009-m020\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">静かに</span>注入する。</li></ul>", "questions": [{"id": "physics-chemistry-009-q001", "questionNo": 21, "question": "<strong>静電気が発生しやすい状況として、誤っているものはどれか。</strong>", "choices": ["危険物を高速で流動・移送させるとき", "危険物をろ過するとき", "湿度が高く、雨が降っているとき", "化学繊維の衣服を着用しているとき"], "answer": 3, "explanation": "解説：湿度が高い環境では電気が逃げやすく、静電気は蓄積しにくくなります。"}, {"id": "physics-chemistry-009-q002", "questionNo": 22, "question": "<strong>タンクへの危険物の注入時における静電気対策として、正しいものはどれか。</strong>", "choices": ["注入管の先端を液面の高い位置に保持し、落差をつけて注入する。", "注入管の先端をタンクの底部付近に保持し、流速を遅くする。", "注入速度をできるだけ速くし、短時間で作業を終える。", "静電気対策は、注入作業には特に必要ない。"], "answer": 2, "explanation": "解説：注入管の先端を底部付近に保持し、落差を小さくし、流速を遅くすることが静電気対策になります。"}, {"id": "physics-chemistry-009-q003", "questionNo": 23, "question": "<strong>静電気の蓄積を抑えるための対策として、誤っているものはどれか。</strong>", "choices": ["設備を接地する。", "導電性の高い帯電防止靴を使用する。", "化学繊維の衣服を着用する。", "室内の湿度を高く保つ。"], "answer": 3, "explanation": "解説：化学繊維は静電気を帯びやすいため、対策としては木綿など帯電しにくい素材を選びます。"}, {"id": "physics-chemistry-009-q004", "questionNo": 24, "question": "<strong>物体が帯電する仕組みに関する記述として、正しいものはどれか。</strong>", "choices": ["物体間を主に移動するのは陽子である。", "物体間を電子が移動しても、電気量の総和は保存される。", "電子を失った物体は負に帯電する。", "同じ符号の電荷どうしは引き合う。"], "answer": 2, "explanation": "解説：帯電では主に電子が物体間を移動し、電気量の総和は保存されます。電子を失うと正、受け取ると負に帯電し、同符号どうしは反発します。"}]}, {"id": "physics-chemistry-010", "chapter": 2, "chapterTitle": "基礎的な物理・化学", "itemNo": 10, "title": "物質の三態と状態変化", "intro": "<p>物質は、温度や圧力によって固体・液体・気体の三つの状態をとります。</p><p>固体が液体になる融解、液体が気体になる気化など、状態が変わっても物質の種類そのものは変わりません。状態変化には熱の吸収や放出が伴い、液体の表面だけで起こる蒸発と、液体全体で起こる沸騰は異なります。</p><p>要点では、状態変化の名称、吸熱・放熱、蒸発と沸騰の違いを押さえます。</p>", "introImage": "images/physics-chemistry-010.png", "introImageAlt": "物質の三態と状態変化を示すイラスト", "body": "<p>物質は、温度によって固体・液体・気体の状態を変える。</p><ul><li>固体から液体への変化を<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-010-m001\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">融解</span>、液体から固体への変化を<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-010-m002\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">凝固</span>という。</li><li>液体から気体への変化を<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-010-m003\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">気化</span>、気体から液体への変化を<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-010-m004\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">凝縮</span>という。</li><li>固体と気体の間を、液体を経ずに直接変化する現象を<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-010-m005\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">昇華</span>という。</li><li>蒸発は、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-010-m006\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">液体の表面から気化する</span>現象で、沸点より低い温度でも起こる。</li><li>沸騰は、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-010-m007\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">液体の内部からも気化が起こる</span>現象である。</li><li>融解、気化、固体から気体への昇華では、物質は周囲から熱を<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-010-m008\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">吸収する</span>。</li><li>凝固、凝縮、気体から固体への昇華では、物質は周囲へ熱を<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-010-m009\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">放出する</span>。</li><li>純物質を一定圧力で状態変化させている間は、加熱や冷却を続けても温度が原則として一定に保たれる。加えた熱や奪われた熱が、状態を変えるために使われるからである。</li><li>混合物は、状態変化中の温度が<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-010-m010\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">一定とは限らない</span>。</li></ul>", "questions": [{"id": "physics-chemistry-010-q001", "questionNo": 25, "question": "<strong>気体から固体への状態変化の名称として、正しいものはどれか。</strong>", "choices": ["融解", "蒸発", "昇華", "凝縮"], "answer": 3, "explanation": "解説：固体から気体、または気体から固体へ直接変化する現象を昇華といいます。液体を経由しない点が特徴です。"}, {"id": "physics-chemistry-010-q002", "questionNo": 26, "question": "<strong>状態変化と熱の出入りに関する記述として、正しいものはどれか。</strong>", "choices": ["液体が気体になる気化では、周囲から熱を吸収する。", "気体が液体になる凝縮では、周囲から熱を吸収する。", "融解中は、加熱するほど温度が上がり続ける。", "状態変化では、必ず新しい物質が生じる。"], "answer": 1, "explanation": "解説：気化や融解は吸熱、凝縮や凝固は放熱です。状態変化は物理変化であり、純物質では状態変化中の温度は原則として一定です。"}]}, {"id": "physics-chemistry-011", "chapter": 2, "chapterTitle": "基礎的な物理・化学", "itemNo": 11, "title": "沸点と蒸気圧", "intro": "<p>液体の表面から飛び出した分子がつくる圧力を蒸気圧といい、温度が上がるほど大きくなります。蒸気圧が周囲の気圧と等しくなると、液体内部からも気泡が生じて沸騰します。</p><p>そのときの温度が沸点です。外気圧が低い場所では低い温度で沸騰します。</p><p>要点では、温度・蒸気圧・沸点・外気圧の関係と、蒸気圧が高い液体ほど揮発しやすいことを判断します。</p>", "introImage": "images/physics-chemistry-011.png", "introImageAlt": "沸点と蒸気圧を示すイラスト", "body": "<p>密閉容器内で、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-011-m001\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">液体が蒸発する量</span>と<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-011-m002\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">蒸気が液体に戻る量</span>が等しい状態を<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-011-m003\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">気液平衡</span>という。</p><ul><li>このとき蒸気が示す圧力を<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-011-m004\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">飽和蒸気圧</span>という。</li><li>同じ液体では、液温が高いほど飽和蒸気圧は<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-011-m005\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">大きい</span>。</li><li>沸点は、液体の<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-011-m006\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">飽和蒸気圧</span>が<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-011-m007\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">外気圧</span>と等しくなる温度である。</li><li>外気圧が低いと沸点は<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-011-m008\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">低くなる</span>。外気圧が高いと沸点は<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-011-m009\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">高くなる</span>。</li><li>同じ温度では、飽和蒸気圧が高い液体ほど<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-011-m010\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">蒸発しやすい</span>。この蒸発しやすさを<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-011-m011\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">揮発性</span>という。</li></ul>", "questions": [{"id": "physics-chemistry-011-q001", "questionNo": 27, "question": "<strong>飽和蒸気圧に関する記述として、正しいものはどれか。</strong>", "choices": ["液温が高くなるほど、飽和蒸気圧は小さくなる。", "液温が高くなるほど、飽和蒸気圧は大きくなる。", "飽和蒸気圧は、液体の種類に関係なく一定である。", "飽和蒸気圧は、揮発性の低い物質ほど大きくなる。"], "answer": 2, "explanation": "解説：液温が高くなるほど飽和蒸気圧は大きくなります。飽和蒸気圧が大きい物質ほど蒸発しやすい傾向があります。"}, {"id": "physics-chemistry-011-q002", "questionNo": 28, "question": "<strong>高山で水の沸点が100℃より低くなる理由として、正しいものはどれか。</strong>", "choices": ["高山では気圧が高くなるため。", "高山では気圧が低くなるため。", "高山では水の比重が変化するため。", "高山と平地で沸点に差は生じない。"], "answer": 2, "explanation": "解説：高山では外圧が低くなるため、飽和蒸気圧が外圧と等しくなる温度、つまり沸点も低くなります。"}]}, {"id": "physics-chemistry-012", "chapter": 2, "chapterTitle": "基礎的な物理・化学", "itemNo": 12, "title": "比重と蒸気比重", "intro": "<p>比重は、液体や固体の重さを同じ体積の水と比べた値で、1より小さければ水に浮き、1より大きければ沈むのが基本です。ただし、水に溶ける液体では単純な二層にならないことがあります。</p><p>蒸気比重は、蒸気の重さを空気と比べた値です。第4類危険物の蒸気の多くは空気より重く、床面やくぼ地に流れてたまります。</p><p>要点では、浮沈と蒸気の滞留方向を判断します。</p>", "introImage": "images/physics-chemistry-012.png", "introImageAlt": "比重と蒸気比重を示すイラスト", "body": "<p>液体の<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-012-m001\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">比重</span>は、同じ体積の<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-012-m002\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">水の質量を1として</span>、液体の質量を比べた値である。</p><ul><li>水に溶けず水と互いに混ざらない液体の場合、比重が1未満なら<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-012-m003\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">水に浮き</span>、1より大きければ<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-012-m004\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">水に沈む</span>。</li><li>水と混ざる液体には、浮く・沈むという判断をそのまま使えない。</li><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-012-m005\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">蒸気比重</span>は、同じ温度・圧力で、同じ体積の<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-012-m006\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">空気の質量を1として</span>比べた値である。</li><li>蒸気比重が1より大きい蒸気は、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-012-m007\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">空気より重い</span>。換気が悪い場所では、床面やくぼみなどの<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-012-m008\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">低所に滞留しやすい</span>。</li><li>第4類危険物の蒸気の多くは、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-012-m009\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">空気より重い</span>。</li></ul>", "questions": [{"id": "physics-chemistry-012-q001", "questionNo": 29, "question": "<strong>比重が１未満の液体について、正しいものはどれか。</strong>", "choices": ["水より重く、水に沈む。", "水より軽く、水に浮く。", "必ず水に溶ける。", "必ず空気より重い蒸気を出す。"], "answer": 2, "explanation": "解説：液体の比重は水を基準１として比較します。比重１未満の液体は水より軽く、水に浮きます。"}, {"id": "physics-chemistry-012-q002", "questionNo": 30, "question": "<strong>蒸気比重が１より大きいことが意味する内容として、正しいものはどれか。</strong>", "choices": ["その蒸気は空気より軽く、高所に滞留しやすい。", "その蒸気は空気より重く、低所に滞留しやすい。", "蒸気比重と滞留位置には関係がない。", "その蒸気は必ず水に溶ける。"], "answer": 2, "explanation": "解説：蒸気比重は空気を基準１として比較します。１より大きい蒸気は空気より重く、低所に滞留しやすいため換気が重要です。"}]}, {"id": "physics-chemistry-013", "chapter": 2, "chapterTitle": "基礎的な物理・化学", "itemNo": 13, "title": "気体の法則と熱膨張", "intro": "<p>気体は、圧力・体積・温度の変化によって大きく膨張・収縮します。</p><p>温度が一定なら圧力を高くすると体積が小さくなり、圧力が一定なら絶対温度が高くなるほど体積が大きくなります。密閉容器では、加熱して体積が変えられないと圧力が上昇します。</p><p>要点では、ボイル・シャルルの法則の比例・反比例、絶対温度への換算、容器やタンクを加熱した場合の危険を押さえます。</p>", "introImage": "images/physics-chemistry-013.png", "introImageAlt": "気体の法則と熱膨張を示すイラスト", "body": "<p>気体の体積や圧力は、温度によって変化する。</p><ul><li><span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-013-m001\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">ボイルの法則</span>では、温度が一定のとき、気体の体積は<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-013-m002\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">圧力に反比例する</span>。</li><li>圧力を2倍にすると、体積は<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-013-m003\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">2分の1</span>になる。</li><li><span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-013-m004\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">圧力</span>×<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-013-m005\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">体積</span>は一定となる。</li><li><span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-013-m006\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">シャルルの法則</span>では、圧力が一定のとき、気体の体積は<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-013-m007\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">絶対温度に比例する</span>。</li><li><span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-013-m008\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">容積が変わらない密閉容器</span>では、気体の圧力は<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-013-m009\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">絶対温度に比例する</span>。密閉容器を加熱すると、内部の圧力は<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-013-m010\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">上がる</span>。</li><li>試験の概算では、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-013-m011\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">絶対温度［K］＝摂氏温度［℃］＋273</span>とすることが多い。</li></ul>", "questions": [{"id": "physics-chemistry-013-q001", "questionNo": 31, "question": "<strong>圧力が一定のとき、気体の体積と絶対温度の関係を表す法則として、正しいものはどれか。</strong>", "choices": ["ボイルの法則", "シャルルの法則", "ドルトンの分圧の法則", "ファラデーの法則"], "answer": 2, "explanation": "解説：圧力が一定のとき、気体の体積は絶対温度に比例します。これをシャルルの法則といいます。"}, {"id": "physics-chemistry-013-q002", "questionNo": 32, "question": "<strong>気体・液体・固体の熱膨張率の大小関係として、正しいものはどれか。</strong>", "choices": ["気体＞液体＞固体", "固体＞液体＞気体", "液体＞気体＞固体", "三者の熱膨張率は常に等しい"], "answer": 1, "explanation": "解説：一般に、熱膨張率は気体が最も大きく、次に液体、固体の順になります。"}]}, {"id": "physics-chemistry-014", "chapter": 2, "chapterTitle": "基礎的な物理・化学", "itemNo": 14, "title": "熱量・比熱・熱の移動", "intro": "<p>物質の温度を上げるには熱が必要で、その量は物質の質量、比熱、温度差で決まります。</p><p>比熱が大きい物質ほど、同じ質量を同じ温度だけ上げるのに多くの熱が必要です。熱は、固体内を伝わる伝導、液体や気体の移動による対流、電磁波として伝わる放射で移動します。</p><p>要点では、Q＝mcΔTの計算と、火災場面での熱移動の具体例を区別します。</p>", "introImage": "images/physics-chemistry-014.png", "introImageAlt": "熱量・比熱・熱の移動を示すイラスト", "body": "<p>比熱とは、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-014-m001\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">物質1 gの温度を1℃上げるために必要な熱量</span>である。</p><p>熱量は、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-014-m002\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">Q＝mcΔT</span>で求める。</p><ul><li>Q：熱量。単位はジュール（J）。</li><li>m：質量。この節ではグラム（g）を使う。</li><li>c：比熱。単位はJ/(g・℃)。</li><li>ΔT：温度差。最後の温度－最初の温度で求める。</li><li>質量をg、比熱をJ/(g・℃)、温度差を℃でそろえると、熱量はJになる。</li><li>温度差は、℃で表してもKで表しても数値は同じである。</li></ul>", "questions": [{"id": "physics-chemistry-014-q001", "questionNo": 33, "question": "<strong>比熱が大きい物質の性質に関する記述として、正しいものはどれか。</strong>", "choices": ["同じ熱量を加えた場合、温度が上昇しやすい。", "同じ熱量を加えた場合、温度が上昇しにくい。", "比熱の大小は、温度変化のしやすさに影響しない。", "比熱が大きい物質は、必ず比重も大きい。"], "answer": 2, "explanation": "解説：比熱が大きい物質は、同じ熱量を加えても温度が上がりにくくなります。水は比熱が大きく、冷却消火に向いています。"}, {"id": "physics-chemistry-014-q002", "questionNo": 34, "question": "<strong>熱の伝導に関する記述として、正しいものはどれか。</strong>", "choices": ["流体の移動によって熱が運ばれる現象である。", "物質を構成する分子・原子の振動が伝わることで熱が移動する現象である。", "電磁波として熱が空間を伝わる現象である。", "固体では熱伝導は起こらない。"], "answer": 2, "explanation": "解説：伝導は、物質内部で分子・原子の振動が伝わることで熱が移動する現象です。流体の移動は対流、電磁波による伝達は放射です。"}]}, {"id": "physics-chemistry-015", "chapter": 2, "chapterTitle": "基礎的な物理・化学", "itemNo": 15, "title": "物理変化と化学変化", "intro": "<p>物質の変化には、形や状態だけが変わる物理変化と、別の物質が生じる化学変化があります。</p><p>氷が水になる、液体が蒸発する、物質を水に溶かすなどは、物質の種類が変わらない物理変化です。燃焼、さび、中和などは新しい物質が生じる化学変化です。</p><p>要点では、見た目が大きく変化しても物質の種類が変わったかどうかを基準に分類します。</p>", "introImage": "images/physics-chemistry-015.png", "introImageAlt": "物理変化と化学変化を示すイラスト", "body": "<p>物質の変化は、物理変化と化学変化に分けられる。</p><ul><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-015-m001\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">物理変化</span>：状態や形が変わっても、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-015-m002\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">新しい物質は生じない</span>。</li><li>例：<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-015-m003\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">融解</span>、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-015-m004\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">凝固</span>、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-015-m005\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">気化</span>、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-015-m006\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">凝縮</span>、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-015-m007\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">昇華</span>、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-015-m008\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">溶解</span></li><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-015-m009\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">化学変化</span>：反応によって、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-015-m010\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">新しい物質が生じる</span>。</li><li>例：<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-015-m011\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">燃焼</span>、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-015-m012\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">さび</span>、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-015-m013\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">中和</span></li></ul>", "questions": [{"id": "physics-chemistry-015-q001", "questionNo": 35, "question": "<strong>次のうち、物理変化に分類されるものとして、正しいものはどれか。</strong>", "choices": ["鉄が錆びる。", "紙が燃える。", "ドライアイスが昇華して気体の二酸化炭素になる。", "中和反応が起こる。"], "answer": 3, "explanation": "解説：ドライアイスの昇華は、分子構造が変化せず、状態だけが変わる物理変化です。"}, {"id": "physics-chemistry-015-q002", "questionNo": 36, "question": "<strong>物理変化と化学変化を区別する基準として、正しいものはどれか。</strong>", "choices": ["物質の色が変化するかどうかで判断する。", "物質の分子構造が変化し、新しい物質が生成するかどうかで判断する。", "物質の温度が変化するかどうかで判断する。", "物質の質量が変化するかどうかで判断する。"], "answer": 2, "explanation": "解説：化学変化では分子構造が変化し、新しい物質が生成します。物理変化では状態や形が変わっても、基本的に物質そのものは変わりません。"}]}, {"id": "physics-chemistry-016", "chapter": 2, "chapterTitle": "基礎的な物理・化学", "itemNo": 16, "title": "単体・化合物・混合物", "intro": "<p>物質は、構成のしかたによって単体・化合物・混合物に分けられます。</p><p>酸素や鉄のように1種類の元素だけでできたものが単体、水のように複数の元素が一定の割合で結び付いたものが化合物です。空気やガソリンのように複数の物質が混ざり、成分比が一定でないものは混合物です。</p><p>要点では、代表物質の分類と、純物質と混合物の融点・沸点の違いを押さえます。</p>", "introImage": "images/physics-chemistry-016.png", "introImageAlt": "単体・化合物・混合物を示すイラスト", "body": "<p>物質は、単体・化合物・混合物などに分類される。</p><ul><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-016-m001\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">元素</span>は、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-016-m002\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">原子の種類</span>を表す名称である。</li><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-016-m003\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">単体</span>は、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-016-m004\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">1種類の元素だけ</span>からなる純物質である。酸素や硫黄などが例である。</li><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-016-m005\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">化合物</span>は、複数の元素が<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-016-m006\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">決まった割合で結び付いた</span>純物質である。水や二酸化炭素などが例である。</li><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-016-m007\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">混合物</span>は、複数の純物質が、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-016-m008\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">性質を保ったまま</span>混ざったものである。<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-016-m009\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">成分の割合は一定とは限らない</span>。</li><li>空気、ガソリン、灯油、軽油などは<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-016-m010\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">混合物</span>である。</li><li>ガソリンは多種類の成分を含むため、一つの決まった沸点ではなく、沸騰する温度に幅がある。</li></ul>", "questions": [{"id": "physics-chemistry-016-q001", "questionNo": 37, "question": "<strong>次のうち、化合物に分類されるものとして、正しいものはどれか。</strong>", "choices": ["空気", "ガソリン", "水（H₂O）", "海水"], "answer": 3, "explanation": "解説：水（H₂O）は、水素と酸素が一定の割合で化学的に結合した化合物です。"}, {"id": "physics-chemistry-016-q002", "questionNo": 38, "question": "<strong>単体に分類されるものとして、正しいものはどれか。</strong>", "choices": ["二酸化炭素", "硫黄", "塩化ナトリウム", "エタノール"], "answer": 2, "explanation": "解説：硫黄（S）は１種類の元素のみからできている単体です。二酸化炭素やエタノールは化合物です。"}, {"id": "physics-chemistry-016-q003", "questionNo": 39, "question": "<strong>ガソリンが単一の沸点を持たず、沸騰範囲を持つ理由として、正しいものはどれか。</strong>", "choices": ["ガソリンが化合物であるため。", "ガソリンが多種類の炭化水素からなる混合物であるため。", "ガソリンが単体であるため。", "ガソリンには沸点という概念が存在しないため。"], "answer": 2, "explanation": "解説：ガソリンは多種類の炭化水素からなる混合物であり、各成分の沸点が異なるため、沸点に幅があります。"}, {"id": "physics-chemistry-016-q004", "questionNo": 40, "question": "<strong>次のうち、炭素を含むが無機化合物として扱われるものはどれか。</strong>", "choices": ["メタノール", "二酸化炭素", "ベンゼン", "酢酸"], "answer": 2, "explanation": "解説：二酸化炭素は炭素を含みますが、単純な炭素化合物として無機化合物に分類されます。"}, {"id": "physics-chemistry-016-q005", "questionNo": 41, "question": "<strong>芳香族炭化水素に分類される物質として、正しいものはどれか。</strong>", "choices": ["メタン", "プロパン", "ベンゼン", "エチレン"], "answer": 3, "explanation": "解説：ベンゼンはベンゼン環を持つ芳香族炭化水素です。メタンやプロパンはアルカン、エチレンは不飽和炭化水素です。"}]}, {"id": "physics-chemistry-017", "chapter": 2, "chapterTitle": "基礎的な物理・化学", "itemNo": 17, "title": "原子・分子・イオンとmol計算", "intro": "<p>物質は原子からできており、原子が結び付いたまとまりを分子といいます。</p><p>原子や分子が電子を失ったり受け取ったりして電気を帯びたものがイオンです。化学では、非常に多い粒子の個数をまとめて扱うためにmolという単位を使います。</p><p>要点では、陽イオン・陰イオンの成り立ち、質量・モル質量・物質量の関係、標準状態における気体体積の基本計算を押さえます。</p>", "introImage": "images/physics-chemistry-017.png", "introImageAlt": "原子・分子・イオンとmol計算を示すイラスト", "body": "<h3>原子・分子・イオン</h3><p><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-017-m001\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">原子</span>は、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-017-m002\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">元素を構成する基本的な粒子</span>である。</p><ul><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-017-m003\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">分子</span>は、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-017-m004\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">複数の原子が結び付いた粒子</span>である。分子からできた物質では、その物質の性質を示す最小のまとまりとなる。</li><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-017-m005\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">イオン</span>は、電子を失うか受け取り、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-017-m006\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">電荷を帯びた粒子</span>である。</li><li>原子が電子を失うと、正の電荷をもつ<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-017-m007\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">陽イオン</span>になる。</li><li>原子が電子を受け取ると、負の電荷をもつ<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-017-m008\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">陰イオン</span>になる。</li></ul><h3>molとモル質量</h3><p>molは、原子や分子などの粒子の個数をまとめて表す物質量の単位である。</p><ul><li>1 molには、約6.0×10²³個の粒子が含まれる。</li><li>モル質量Mは、物質1 mol当たりの質量である。単位はg/molである。</li><li>例えば、水H₂Oのモル質量は、水素1×2＋酸素16＝<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-017-m009\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">18</span>より、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-017-m010\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">18</span> g/molである。したがって、水1 molの質量は<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-017-m011\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">18</span> g、2 molの質量は<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-017-m012\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">36</span> gである。</li></ul><h3>標準状態の気体</h3><ul><li>気体の標準状態とは、0℃、1気圧（約101.3 kPa）の状態をいう。この状態では、気体1 molの体積は約22.4 Lである。</li><li>問題によっては25℃、1気圧で計算する場合がある。このとき、気体1 molの体積は約24.5 Lとなり、問題文では約24 Lとして扱うこともある。（問題文の条件に従うこと）</li></ul>", "questions": [{"id": "physics-chemistry-017-q001", "questionNo": 42, "question": "<strong>原子・分子・イオンに関する記述として、正しいものはどれか。</strong>", "choices": ["原子が電子を失うと陰イオンになる。", "原子が電子を得ると陽イオンになる。", "原子が電子を失うと陽イオンになる。", "原子はイオンになることができない。"], "answer": 3, "explanation": "解説：原子が電子を失うと正の電荷を帯び、陽イオンになります。電子を得ると陰イオンになります。"}, {"id": "physics-chemistry-017-q002", "questionNo": 43, "question": "<strong>化学反応式における質量保存の法則に関する記述として、正しいものはどれか。</strong>", "choices": ["反応前と反応後で、各原子の数は変化しない。", "反応前と反応後で、各原子の数は必ず増加する。", "反応前と反応後で、物質の質量は変化してもよい。", "質量保存の法則は気体反応にのみ適用される。"], "answer": 1, "explanation": "解説：化学反応式では、反応前後で各原子の数が変わらないように係数を調整します。これが質量保存の法則に対応します。"}, {"id": "physics-chemistry-017-q003", "questionNo": 44, "question": "<strong>水H2Oのモル質量を18g/molとすると、水36gの物質量として、正しいものはどれか。</strong>", "choices": ["0.5mol", "1mol", "2mol", "36mol"], "answer": 3, "explanation": "解説：物質量は、質量をモル質量で割って求めます。36g÷18g/mol＝2molです。"}, {"id": "physics-chemistry-017-q004", "questionNo": 45, "question": "<strong>メタノールの完全燃焼を表す化学反応式として、正しいものはどれか。</strong>", "choices": ["CH3OH＋O2→CO＋2H2O", "2CH3OH＋3O2→2CO2＋4H2O", "2CH3OH＋O2→2CO2＋2H2", "CH3OH→C＋2H2O"], "answer": 2, "explanation": "解説：メタノールの完全燃焼は、2CH3OH＋3O2→2CO2＋4H2Oです。反応前後でC・H・Oの原子数が等しくなることを確認します。"}, {"id": "physics-chemistry-017-q005", "questionNo": 46, "question": "<strong>2molのメタノールを完全燃焼させるために必要な酸素は何molか。反応式は、2CH3OH＋3O2→2CO2＋4H2Oとする。</strong>", "choices": ["1mol", "2mol", "3mol", "4mol"], "answer": 3, "explanation": "解説：反応式の係数比は、メタノール：酸素＝2：3です。したがって、メタノール2molには酸素3molが必要です。"}, {"id": "physics-chemistry-017-q006", "questionNo": 47, "question": "<strong>標準状態で11.2Lの一酸化炭素COの質量は何gか。1mol＝22.4L、C＝12、O＝16とする。</strong>", "choices": ["7g", "14g", "28g", "44g"], "answer": 2, "explanation": "解説：11.2Lは0.5molです。一酸化炭素のモル質量は12＋16＝28g/molなので、0.5×28＝14gです。"}, {"id": "physics-chemistry-017-q007", "questionNo": 48, "question": "<strong>メタン1molを完全燃焼させるために必要な酸素は何molか。反応式は、CH4＋2O2→CO2＋2H2Oとする。</strong>", "choices": ["5mol", "1mol", "2mol", "4mol"], "answer": 3, "explanation": "解説：反応式の係数比は、メタン：酸素＝1：2です。メタン1molには酸素2molが必要です。"}]}, {"id": "physics-chemistry-018", "chapter": 2, "chapterTitle": "基礎的な物理・化学", "itemNo": 18, "title": "酸・塩基・中和", "intro": "<p>水溶液には酸性・中性・塩基性があり、酸は水素イオンを、塩基は水酸化物イオンを生じる性質があります。</p><p>酸性・塩基性の強さはpHで表し、25℃ではpH7が中性です。酸と塩基を適切な量で混ぜると、互いの性質を打ち消して塩と水を生じる中和反応が起こります。</p><p>要点では、リトマス紙、pH、代表的な酸・塩基、中和時の発熱を判断します。</p>", "introImage": "images/physics-chemistry-018.png", "introImageAlt": "酸・塩基・中和を示すイラスト", "body": "<p>酸と塩基は、水溶液中で特徴的なイオンを生じる物質である。</p><ul><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-018-m001\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">酸</span>は、水溶液中で<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-018-m002\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">水素イオンH⁺</span>を生じる。</li><li>酸性の水溶液は、<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-018-m003\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">青色</span>リトマス紙を<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-018-m004\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">赤色</span>に変える。</li><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-018-m005\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">塩基</span>は、水溶液中で<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-018-m006\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">水酸化物イオンOH⁻</span>を生じる。</li><li>塩基性の水溶液は、<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-018-m007\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">赤色</span>リトマス紙を<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-018-m008\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">青色</span>に変える。</li><li>25℃では、pHが<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-018-m009\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">7未満</span>なら<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-018-m010\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">酸性</span>、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-018-m011\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">7</span>なら<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-018-m012\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">中性</span>、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-018-m013\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">7を超える</span>と<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-018-m014\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">塩基性</span>である。</li><li>塩酸や硫酸は酸、水酸化ナトリウム水溶液は塩基の例である。</li><li>中和反応では、酸と塩基から<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-018-m015\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">塩</span>と<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-018-m016\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">水</span>が生じる。</li><li>中和では熱が発生することがあるため、酸と塩基を不用意に混ぜない。</li></ul>", "questions": [{"id": "physics-chemistry-018-q001", "questionNo": 49, "question": "<strong>中和反応に関する記述として、正しいものはどれか。</strong>", "choices": ["酸と塩基が反応して、塩と水を生成する反応である。", "酸と酸化剤が反応して、新たな酸を生成する反応である。", "中和反応では、必ず気体が発生する。", "中和反応は、化学変化ではなく物理変化に分類される。"], "answer": 1, "explanation": "解説：中和反応は、酸と塩基が反応して塩と水を生成する反応です。新しい物質ができるため化学変化です。"}, {"id": "physics-chemistry-018-q002", "questionNo": 50, "question": "<strong>pHが７の水溶液の性質として、正しいものはどれか。</strong>", "choices": ["強い酸性を示す。", "中性を示す。", "強いアルカリ性を示す。", "pHの値だけでは、酸性・アルカリ性を判断できない。"], "answer": 2, "explanation": "解説：pH７は中性です。pH７未満は酸性、pH７超はアルカリ性です。"}]}, {"id": "physics-chemistry-019", "chapter": 2, "chapterTitle": "基礎的な物理・化学", "itemNo": 19, "title": "酸化・還元", "intro": "<p>物質が酸素と結び付く、または水素や電子を失う変化を酸化といい、その逆を還元といいます。</p><p>酸化と還元は必ず同時に起こり、一方を酸化する物質が酸化剤、一方を還元する物質が還元剤です。燃焼は、可燃物が酸素によって酸化される代表的な酸化還元反応です。</p><p>要点では、酸素・水素・電子の増減から酸化と還元を判定し、酸化剤自身は還元されることを押さえます。</p>", "introImage": "images/physics-chemistry-019.png", "introImageAlt": "酸化・還元を示すイラスト", "body": "<p>酸化と還元は、互いに対になって起こる化学変化である。</p><ul><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-019-m001\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">酸化</span>は、物質が酸素を<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-019-m002\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">得る</span>変化である。水素を<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-019-m003\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">失う</span>変化や、電子を<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-019-m004\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">失う</span>変化も酸化である。</li><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-019-m005\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">還元</span>は、物質が酸素を<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-019-m006\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">失う</span>変化である。水素を<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-019-m007\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">得る</span>変化や、電子を<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-019-m008\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">得る</span>変化も還元である。</li><li>ある物質が酸化されるとき、別の物質は<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-019-m009\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">還元</span>される。酸化と還元は同時に起こる。</li><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-019-m010\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">酸化剤</span>は相手を<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-019-m011\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">酸化</span>し、自身は<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-019-m012\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">還元</span>される。</li><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-019-m013\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">還元剤</span>は相手を<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-019-m014\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">還元</span>し、自身は<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-019-m015\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">酸化</span>される。</li><li>燃焼は、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-019-m016\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">可燃物が酸化される</span>代表的な酸化還元反応である。</li></ul>", "questions": [{"id": "physics-chemistry-019-q001", "questionNo": 51, "question": "<strong>還元反応の説明として、正しいものはどれか。</strong>", "choices": ["物質が酸素と結合する反応である。", "物質が水素を失う反応である。", "物質が酸素を失う反応である。", "物質が電子を失う反応である。"], "answer": 3, "explanation": "解説：還元は、酸素を失う、水素と結合する、または電子を受け取る反応です。"}, {"id": "physics-chemistry-019-q002", "questionNo": 52, "question": "<strong>燃焼が酸化還元反応の一種であるとされる理由として、正しいものはどれか。</strong>", "choices": ["燃焼では、可燃物が還元され、酸素が酸化されるため。", "燃焼では、可燃物が酸化され、酸素が還元されるため。", "燃焼は酸化還元反応とは無関係な現象であるため。", "燃焼では、酸化反応のみが起こり、還元反応は起こらないため。"], "answer": 2, "explanation": "解説：燃焼では、可燃物が酸化され、酸素が還元されます。酸化と還元は同時に起こるため、燃焼は酸化還元反応の一種です。"}, {"id": "physics-chemistry-019-q003", "questionNo": 53, "question": "<strong>電気分解における陽極での反応として、正しいものはどれか。</strong>", "choices": ["還元反応が起こる。", "酸化反応が起こる。", "中和反応が起こる。", "燃焼反応が起こる。"], "answer": 2, "explanation": "解説：電気分解は独立して深追いしませんが、陽極で酸化、陰極で還元が起こる関係は酸化還元の基本として押さえます。"}]}, {"id": "physics-chemistry-020", "chapter": 2, "chapterTitle": "基礎的な物理・化学", "itemNo": 20, "title": "混合危険と腐食", "intro": "<p>物質は、単独では安定でも、別の物質と混ざることで急激に発熱したり、発火・爆発したり、有毒ガスを発生したりすることがあります。これが混合危険です。</p><p>また、金属が水分や酸素などと反応して劣化する現象を腐食といいます。危険物施設では、誤混合の防止と設備の腐食対策が重要です。</p><p>要点では、危険な組合せ、腐食を進める条件、塗装・耐食材料・電気防食などを判断します。</p>", "introImage": "images/physics-chemistry-020.png", "introImageAlt": "混合危険と腐食を示すイラスト", "body": "<p>混合危険とは、物質の組合せによって、<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-020-m001\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">発熱</span>・<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-020-m002\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">発火</span>・<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-020-m003\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">爆発</span>・<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-020-m004\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">有害ガス発生</span>などが起こる危険をいう。</p><ul><li>酸化性物質と可燃性物質を混ぜると、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-020-m005\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">激しい反応</span>が起こることがある。</li><li>酸と塩基を急に混ぜると、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-020-m006\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">中和熱</span>によって液温が上がり、飛散することがある。</li><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-020-m007\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">禁水性物質</span>の中には、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-020-m008\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">水</span>と反応して<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-020-m009\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">発熱</span>・<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-020-m010\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">発火</span>したり、<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-020-m011\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">可燃性ガス</span>を発生したりするものがある。</li><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-020-m012\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">腐食</span>は、金属が酸素、水、酸などと反応し、劣化する現象である。</li><li>一般に、<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-020-m013\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">温度や湿度が高く</span>、水分中に塩類などの<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-020-m014\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">電解質がある</span>と、腐食が進みやすい。</li></ul><p>主な防食方法は、次のとおりである。</p><ul><li><span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-020-m015\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">水分や電解質</span>との接触を減らす。</li><li>金属表面へ<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-020-m016\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">防食塗装</span>を行う。</li><li>内容物に適した<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-020-m017\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">耐食性材料を使う</span>。</li><li>地下タンクや配管などに<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-020-m018\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">電気防食</span>を行う。</li></ul>", "questions": [{"id": "physics-chemistry-020-q001", "questionNo": 54, "question": "<strong>禁水性物質と水の接触によって生じる危険として、正しいものはどれか。</strong>", "choices": ["中和反応により、無害な塩が生成される。", "可燃性ガスの発生や発火が起こるおそれがある。", "何の反応も起こらず、安全に処理できる。", "禁水性物質は、水と接触しても性質が変化しない。"], "answer": 2, "explanation": "解説：禁水性物質が水と接触すると、可燃性ガスの発生や発火が起こるおそれがあります。"}, {"id": "physics-chemistry-020-q002", "questionNo": 55, "question": "<strong>異種金属の接触によって生じる腐食に関する記述として、正しいものはどれか。</strong>", "choices": ["異種金属を接触させても、腐食には影響しない。", "電解質を介して異種金属が接触すると、イオン化傾向の大きい金属が早く腐食する。", "電解質を介して異種金属が接触すると、イオン化傾向の小さい金属が早く腐食する。", "同種金属同士の接触でのみ発生する。"], "answer": 2, "explanation": "解説：水分などの電解質を介して異種金属が接触すると、イオン化傾向の大きい金属が腐食しやすくなります。"}, {"id": "physics-chemistry-020-q003", "questionNo": 56, "question": "<strong>地下タンク・配管の腐食対策として、正しいものはどれか。</strong>", "choices": ["防食塗装や電気防食を施す。", "腐食対策は不要であり、自然に放置してよい。", "異種金属を積極的に組み合わせて使用する。", "海水を用いて配管を洗浄する。"], "answer": 1, "explanation": "解説：地下タンクや配管には、防食塗装や電気防食などの腐食対策を行います。塩分や水分は腐食を促進するため注意が必要です。"}]}, {"id": "physics-chemistry-021", "chapter": 2, "chapterTitle": "基礎的な物理・化学", "itemNo": 21, "title": "主な気体の性質", "intro": "<p>火災や消火を理解するには、空気を構成する気体や燃焼で発生する気体の性質を知る必要があります。酸素は自ら燃えませんが燃焼を助け、窒素と二酸化炭素は不燃性です。</p><p>ただし、高濃度になると酸素濃度を下げて窒息を起こします。水素と一酸化炭素は可燃性で、一酸化炭素には強い毒性があります。</p><p>要点では、空気中の割合、燃焼性、支燃性、毒性、空気との重さを対応させます。</p>", "introImage": "images/physics-chemistry-021.png", "introImageAlt": "主な気体の性質を示すイラスト", "body": "<h3>酸素</h3><ul><li>乾燥空気中に<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-021-m001\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">約21 vol％</span>含まれる。</li><li>酸素自体は燃える物質ではなく、不燃性である。ただし、ほかの物質の燃焼を助ける<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-021-m002\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">支燃性</span>をもつ。</li><li>酸素の濃度が高くなるほど、燃焼は激しくなりやすい。</li></ul><h3>窒素</h3><ul><li>乾燥空気中に<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-021-m003\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">約78 vol％</span>含まれる。</li><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-021-m004\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">不燃性</span>である。</li></ul><h3>二酸化炭素</h3><ul><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-021-m005\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">不燃性</span>で、空気より<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-021-m006\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">重い</span>。</li><li>周囲の酸素濃度を下げる<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-021-m007\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">窒息作用</span>により、消火に使われる。</li><li>高濃度の二酸化炭素は人体にも危険であり、<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-021-m008\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">酸素欠乏</span>や<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-021-m009\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">窒息</span>のおそれがある。</li></ul><h3>水素</h3><ul><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-021-m010\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">可燃性</span>で、空気より<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-021-m011\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">軽い</span>。</li><li>燃焼範囲が<span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-021-m012\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">広い</span>。</li></ul><h3>一酸化炭素</h3><ul><li><span class=\"marker marker-blue\" data-marker-id=\"physics-chemistry-021-m013\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"blueマーカーを表示\">無色・無臭</span>で、空気とほぼ同じ重さである。</li><li><span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-021-m014\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">可燃性</span>があり、強い<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-021-m015\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">毒性</span>をもつ。</li><li>炭素を含む物質の<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-021-m016\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">不完全燃焼</span>によって生じる。</li></ul><h3>空気</h3><ul><li>乾燥空気は、およそ窒素78 vol％、酸素21 vol％、その他の気体1 vol％からなる<span class=\"marker marker-red\" data-marker-id=\"physics-chemistry-021-m017\" role=\"button\" tabindex=\"0\" aria-pressed=\"false\" aria-label=\"redマーカーを表示\">混合物</span>である。</li></ul>", "questions": [{"id": "physics-chemistry-021-q001", "questionNo": 57, "question": "<strong>空気の組成に関する記述として、正しいものはどれか。</strong>", "choices": ["窒素が約78vol％、酸素が約21vol％を占める。", "酸素が約78vol％、窒素が約21vol％を占める。", "二酸化炭素が主成分である。", "空気はすべて窒素から構成される。"], "answer": 1, "explanation": "解説：空気は主に窒素約78vol％、酸素約21vol％からなる混合物です。"}, {"id": "physics-chemistry-021-q002", "questionNo": 58, "question": "<strong>二酸化炭素消火剤が消火に用いられる理由として、正しいものはどれか。</strong>", "choices": ["二酸化炭素が可燃性であり、燃焼を助けるため。", "二酸化炭素が不燃性・不活性であり、酸素濃度を低下させて窒息効果を発揮するため。", "二酸化炭素は冷却効果のみを持ち、窒息効果は持たないため。", "二酸化炭素は油と中和反応を起こすため。"], "answer": 2, "explanation": "解説：二酸化炭素は不燃性で、酸素濃度を下げることにより窒息消火の効果を発揮します。"}, {"id": "physics-chemistry-021-q003", "questionNo": 59, "question": "<strong>酸素の性質に関する記述として、正しいものはどれか。</strong>", "choices": ["酸素は可燃性で、それ自体が激しく燃える。", "酸素は支燃性をもち、他の物質の燃焼を助ける。", "酸素は空気より著しく軽い。", "酸素は二酸化炭素より消火に適している。"], "answer": 2, "explanation": "解説：酸素は支燃性をもち、他の物質の燃焼を助けますが、酸素自体が可燃性というわけではありません。"}, {"id": "physics-chemistry-021-q004", "questionNo": 60, "question": "<strong>一酸化炭素と二酸化炭素の性質の組合せとして、正しいものはどれか。</strong>", "choices": ["一酸化炭素は可燃性・有毒、二酸化炭素は不燃性である。", "一酸化炭素は不燃性、二酸化炭素は可燃性である。", "どちらも可燃性で、毒性はない。", "どちらも空気より軽く、消火には使えない。"], "answer": 1, "explanation": "解説：一酸化炭素は可燃性で強い毒性をもちます。二酸化炭素は不燃性で、酸素濃度を下げる窒息作用により消火に利用されます。"}]}];
